                        mapping?: {
                            [key: string]: "fecha" | "hora" | "monto" | "oc" | "authCode" | "cardLast4" | "tipoPago" | "marca" | "cuotas" | "apellido" | "correo" | "nombre" | "formulario" | "moneda" | "telefono" | "dealId" | "producto" | "transactionId" | "estado" | "tipoTransaccion" | "terminal" | "ignore";
                        };
                        save_mapping?: boolean;
