                                checked_at: string;
                                health: {
                                    score: number;
                                    tracking_healthy: boolean;
                                } | null;
                                /** @description True ⇒ the Cox fatigue read FAILED, so every `fatigue` below is null for that reason rather than because nothing is fatiguing. Fatigue is the one signal that OVERRIDES a `room_to_scale` verdict, so this is the difference between "safe to scale" and "we could not check whether this ad is dying". */
                                fatigue_unavailable: boolean;
