            parameters: {
                query?: never;
                header?: never;
                path: {
                    workspaceId: string;
                };
                cookie?: never;
            };
            requestBody?: {
                content: {
                    "application/json": {
                        items: {
                            /** Format: uuid */
                            profile_id: string;
                            /** @example clinic.cl */
                            domain: string;
                            /** Format: uuid */
                            account_id: string;
                            /**
                             * @description Defaults to `trk`.
                             * @example trk
                             */
                            host?: string;
                        }[];
                    };
                };
            };
